package crew

// Regression tests for tmux send-keys split behaviour.
//
// # Background
//
// gig-4040: --prompt text was pasted into a worker pane but Enter was never
// sent because SendCommand chained both operations in a single tmux invocation
// (\; syntax). Tmux processed the paste but dropped the Enter.
//
// gig-33ab: The same chained-invocation pattern survived in the shell script
// generated by buildWorkerStopScript in hooks/builtin.go.
//
// # Invariant
//
// Every code path that types text into a tmux pane MUST use two separate
// tmux process invocations:
//
//  1. tmux send-keys -t TARGET -l "TEXT"   (paste, literal flag)
//  2. tmux send-keys -t TARGET Enter       (submit, no -l flag)
//
// A single invocation that contains both "-l" and "Enter" is the broken
// pattern. These tests exist to catch any reintroduction of it.

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// withFakeTmux installs a stub tmux binary that records every invocation as a
// space-joined argument string (one line per call) in a log file.  It patches
// PATH for the duration of the test via t.Setenv and returns a reader func.
// The stub always exits 0 so callers do not need a live tmux session.
func withFakeTmux(t *testing.T) func() []string {
	t.Helper()
	dir := t.TempDir()
	logFile := filepath.Join(dir, "calls.log")
	bin := filepath.Join(dir, "tmux")
	// Use /bin/sh for broadest compatibility.
	script := "#!/bin/sh\necho \"$*\" >> " + logFile + "\n"
	if err := os.WriteFile(bin, []byte(script), 0755); err != nil {
		t.Fatalf("create fake tmux binary: %v", err)
	}
	t.Setenv("PATH", dir+":"+os.Getenv("PATH"))

	return func() []string {
		data, _ := os.ReadFile(logFile)
		var lines []string
		for _, l := range strings.Split(strings.TrimSpace(string(data)), "\n") {
			if l != "" {
				lines = append(lines, l)
			}
		}
		return lines
	}
}

// sendKeysCalls filters recorded tmux invocations to only send-keys calls.
func sendKeysCalls(all []string) []string {
	var out []string
	for _, c := range all {
		if strings.HasPrefix(c, "send-keys ") {
			out = append(out, c)
		}
	}
	return out
}

// assertNoSingleCallCombinesTextAndEnter is the core regression assertion for
// gig-4040 and gig-33ab.
//
// The broken pattern is tmux command chaining within a single process invocation:
//
//	tmux send-keys -t TARGET -l TEXT ; send-keys -t TARGET Enter
//
// tmux interprets ";" as a command separator, so the caller passes it as an
// argument to exec.Command (Go) or escapes it as \; in a shell script.
// Either way, the Enter keystroke races with or is dropped after the paste.
//
// The fix: two separate os/exec invocations — the fake tmux stub records each
// as its own line, so the broken pattern is always detectable as a ";" on one line.
func assertNoSingleCallCombinesTextAndEnter(t *testing.T, calls []string) {
	t.Helper()
	for _, c := range calls {
		// Detect "; send-keys" chaining in a single tmux invocation.
		// Both Go's ";" argument and shell's "\;" appear here after echo "$*".
		if (strings.Contains(c, "; send-keys") || strings.Contains(c, `\; send-keys`)) &&
			strings.Contains(c, " -l ") && strings.Contains(c, "Enter") {
			t.Errorf(
				"regression (gig-4040/gig-33ab): single tmux invocation chains -l paste and Enter via \";\":\n  %q\n"+
					"Fix: two separate tmux process invocations — paste first, Enter second.",
				c,
			)
		}
	}
}

// TestSendCommandUsesTwoSeparateInvocations verifies that SendCommand never
// combines text paste and Enter in a single tmux call.
//
// This is the direct regression test for gig-4040, where SendCommand used
// tmux's ";" chaining (tmuxRun("send-keys", ..., ";", "send-keys", ..., "Enter"))
// and the Enter was dropped by tmux.
func TestSendCommandUsesTwoSeparateInvocations(t *testing.T) {
	calls := withFakeTmux(t)

	if err := SendCommand("jeff:test", "Read your task context"); err != nil {
		t.Fatalf("SendCommand returned error: %v", err)
	}

	got := sendKeysCalls(calls())

	// Must be exactly two send-keys calls: paste then Enter.
	if len(got) != 2 {
		t.Fatalf("want 2 send-keys calls, got %d: %v", len(got), got)
	}

	// First call: paste with -l (literal) flag.
	if !strings.Contains(got[0], " -l ") {
		t.Errorf("first call missing -l flag (paste call): %q", got[0])
	}

	// Second call: Enter key, no -l flag.
	if !strings.Contains(got[1], "Enter") {
		t.Errorf("second call missing Enter: %q", got[1])
	}
	if strings.Contains(got[1], " -l ") {
		t.Errorf("second call must not have -l flag (Enter only): %q", got[1])
	}

	assertNoSingleCallCombinesTextAndEnter(t, got)
}

// TestSendCommandWithMultiWordPrompt confirms the split behaviour holds for
// prompts containing spaces, which is the common --prompt use-case.
func TestSendCommandWithMultiWordPrompt(t *testing.T) {
	calls := withFakeTmux(t)

	prompt := "Read your task context using `gig show` for your task ID and begin working."
	if err := SendCommand("jeff:gig-33ab", prompt); err != nil {
		t.Fatalf("SendCommand: %v", err)
	}

	got := sendKeysCalls(calls())
	if len(got) != 2 {
		t.Fatalf("want 2 send-keys calls for multi-word prompt, got %d: %v", len(got), got)
	}
	assertNoSingleCallCombinesTextAndEnter(t, got)
}

// TestSendTextNeverSendsEnter confirms that SendText is a paste-only primitive:
// exactly one send-keys call with -l, and Enter must not appear anywhere.
// SendText is the building block for two-step delivery; it must never grow an
// implicit Enter.
func TestSendTextNeverSendsEnter(t *testing.T) {
	calls := withFakeTmux(t)

	if err := SendText("jeff:test", "some text"); err != nil {
		t.Fatalf("SendText: %v", err)
	}

	got := sendKeysCalls(calls())
	if len(got) != 1 {
		t.Fatalf("want 1 send-keys call from SendText, got %d: %v", len(got), got)
	}
	if !strings.Contains(got[0], " -l ") {
		t.Errorf("SendText call missing -l flag: %q", got[0])
	}
	if strings.Contains(got[0], "Enter") {
		t.Errorf("SendText must not send Enter: %q", got[0])
	}
}

// TestSendEnterNoLiteralFlag confirms that SendEnter sends exactly the Enter
// key and never uses the -l (literal) flag.  Sending Enter with -l would type
// the literal string "Enter" instead of pressing the key.
func TestSendEnterNoLiteralFlag(t *testing.T) {
	calls := withFakeTmux(t)

	if err := SendEnter("jeff:test"); err != nil {
		t.Fatalf("SendEnter: %v", err)
	}

	got := sendKeysCalls(calls())
	if len(got) != 1 {
		t.Fatalf("want 1 send-keys call from SendEnter, got %d: %v", len(got), got)
	}
	if !strings.Contains(got[0], "Enter") {
		t.Errorf("SendEnter call missing Enter: %q", got[0])
	}
	if strings.Contains(got[0], " -l ") {
		t.Errorf("SendEnter must not use -l flag: %q", got[0])
	}
}

// TestSendCommandInvariant is a table-driven sweep of the core invariant across
// different targets and command strings, including edge cases like empty string,
// strings containing "Enter", and strings with special characters.
func TestSendCommandInvariant(t *testing.T) {
	cases := []struct {
		name    string
		target  string
		command string
	}{
		{"simple", "jeff:gig-1234", "hello world"},
		{"contains-enter-word", "jeff:gig-1234", "Enter the task context"},
		{"special-chars", "jeff:gig-1234", "cat /tmp/foo && grep -n 'bar'"},
		{"backticks", "jeff:gig-1234", "Read your task via `gig show gig-1234`"},
		{"multiline-like", "jeff:gig-1234", "line one\nline two"},
		{"empty", "jeff:gig-1234", ""},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			calls := withFakeTmux(t)

			if err := SendCommand(tc.target, tc.command); err != nil {
				t.Fatalf("SendCommand(%q): %v", tc.command, err)
			}

			got := sendKeysCalls(calls())
			if len(got) != 2 {
				t.Fatalf("want 2 send-keys calls, got %d: %v", len(got), got)
			}
			assertNoSingleCallCombinesTextAndEnter(t, got)
		})
	}
}
